#!/usr/bin/env python3
"""Results pack for both tests (Phase 4g; prompts/06_finish.md section 5). No new estimation.
Usage: python3 code/python/04g_results_pack.py --date YYYY-MM-DD
Writes results/<date>/paper/: tables (CSV, .tex), figures with captions, rule_out.csv, findings.md, number_check.csv."""
import argparse, csv, os, shutil, sys
import numpy as np, pandas as pd
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from results_lookup import Ledger, table

ap = argparse.ArgumentParser(); ap.add_argument("--date", required=True); a = ap.parse_args(); D = a.date
P = f"results/{D}/paper"; TB = f"{P}/tables"; FG = f"{P}/figures"; os.makedirs(TB, exist_ok=True); os.makedirs(FG, exist_ok=True)
B = "2026-11-04"  # blocks estimated on Nov 2-4 stay in their own folders (append-only); prompts 08-09 added Nov 7 blocks
H1 = "results/2026-11-02/h1"; H2 = "results/2026-11-03/h2"; H3 = "results/2026-11-03/h3"; MS = "results/2026-11-03/h3_mainspec"; RB = f"results/{B}/robustness"; PL = f"results/{B}/h3_placebo"; FA = f"results/{B}/fang"; ST = f"results/{B}/stretch"; GS = f"results/{B}/georgia_solar"
F8 = "results/2026-11-07/fang"; EX = "results/2026-11-07/extend"; ET = f"{EX}/tables"
for f in (f"{H1}/h1_core.csv", f"{H2}/h2_results.csv", f"{MS}/sdm_impacts.csv", f"{RB}/robustness.csv", f"{PL}/placebo_slx.csv", f"{FA}/fang_results.csv", f"{ST}/stretch.csv", f"{GS}/projection_long.csv", f"{RB}/weather_check.csv", f"{FA}/net_producer_check.csv", f"{FA}/seds_basis_level_check.csv", f"{GS}/capacity_paths.csv"):
    if not os.path.exists(f): sys.exit(f"Missing input: {f}")
def stars(p): return "" if pd.isna(p) else "***" if p < .01 else "**" if p < .05 else "*" if p < .1 else ""
def cl(e, s=None, p=None, d=4): return f"{e:.{d}f}{stars(p)}" + (f" ({s:.{d}f})" if s is not None and not pd.isna(s) else "")
def tex(df, path, cap):
    esc = lambda v: str(v).replace("_", "\\_").replace("%", "\\%").replace("&", "\\&").replace("$", "\\$")
    t = [f"% {cap}", "% Generated by code/python/04g_results_pack.py. Do not edit by hand.", "\\begin{tabular}{l" + "r" * (len(df.columns) - 1) + "}", "\\toprule", " & ".join(esc(c) for c in df.columns) + " \\\\", "\\midrule"]
    t += [" & ".join(esc(v) for v in x.values) + " \\\\" for _, x in df.iterrows()] + ["\\bottomrule", "\\end{tabular}"]; open(path, "w").write("\n".join(t) + "\n")
TABS = []
def save(df, name, cap): df.to_csv(f"{TB}/{name}.csv", index=False); tex(df, f"{TB}/{name}.tex", cap); TABS.append((name, cap)); return df

# ---- Table 1: descriptives ----
p = pd.read_csv("data/out/state_panel_2015_2025.csv"); p50 = p[p.state != "DC"]
f = pd.read_csv("data/fang_panel.csv"); ac = pd.read_csv("data/acs_broadband.csv"); rd = pd.read_csv("data/nsf_state_rd.csv")
V = [(p50, "ai_dc_per1000_lag1", "Private data-center jobs per 1,000 workers, t-1", "BLS QCEW"), (p50, "ln_ec", "ln(retail MWh per person)", "EIA, BEA"), (p50, "ln_ee", "ln(real GDP / retail MWh)", "BEA, EIA"), (p50, "renew_share", "Renewable share of generation", "EIA"), (p50, "new_renew_mw", "Change in renewable capacity, MW", "EIA"), (p50, "solar_share", "Solar share", "EIA"), (p50, "wind_share", "Wind share", "EIA"), (p50, "fossil_to_renew", "Fossil to renewable ratio", "EIA"), (p50, "seds_mmbtu_pc", "Total energy per person, MMBtu", "EIA SEDS"), (p50, "co2_per_mwh_t", "CO2 per MWh, tons", "EIA"), (p50, "ln_gdp_pc", "ln(real GDP per person)", "BEA"), (p50, "manuf_share", "Manufacturing share of GDP", "BEA"), (p50, "price_c_kwh", "Electricity price, cents per kWh", "EIA"), (p50, "pop_growth", "Population growth", "BEA"), (p50, "tech_share", "Tech jobs share (NAICS 5415)", "BLS QCEW"), (p50, "hma", "HMA coupling index", "BLS QCEW"), (p50, "ln_ea", "ln(nonfarm GDP per sq mile)", "BEA, Census"),
     (f, "re_bbtu", "Renewable consumption, billion Btu (Fang)", "EIA SEDS"), (f, "ai_postings", "AI job postings (Fang)", "Stanford AI Index"), (f, "ep_tetcd", "Total energy price, $/MMBtu (Fang)", "EIA SEDS"), (f, "edu_bach_per1000", "Bachelor's degrees per 1,000 age 18-24 (Fang)", "NCSES"), (f, "epu_composite", "EPU composite (Fang)", "Baker, Davis, Levy"), (f, "epu_national", "EPU national", "Baker, Davis, Levy"), (f, "epu_state", "EPU state", "Baker, Davis, Levy"), (f, "target_pct", "LBNL current RPS/CES schedule, percent", "LBNL"), (ac[ac.year >= 2016], "broadband_pct", "Household broadband, percent (2016-2024)", "Census ACS"), (rd, "rd_total_musd", "R&D, $M (2017-2023)", "NSF")]
save(pd.DataFrame([dict(Variable=n, Mean=round(d[v].mean(), 3), SD=round(d[v].std(), 3), Min=round(d[v].min(), 3), Max=round(d[v].max(), 3), N=int(d[v].notna().sum()), Source=s) for d, v, n, s in V]), "table1_descriptives", "Descriptive statistics, before winsorizing. Zhang rows: 50 states. Fang rows: 50 states + DC.")

# ---- Table 2: H1 ----
c = pd.read_csv(f"{H1}/h1_core.csv"); c = c[c.controls == "ctrl4"]; x = pd.read_csv(f"{H1}/h1_extras.csv")
ex = [("solar_share", "h1x_twfe_ai518210_lag1_ctrl4_w9901_cl-state_solar_share_50s2015_2025"), ("wind_share", "h1x_twfe_ai518210_lag1_ctrl4_w9901_cl-state_wind_share_50s2015_2025"), ("fossil_to_renew", "h1x_twfe_ai518210_lag1_ctrl4_w9901_cl-state_fossil_to_renew_50s2015_2025"), ("coal_share", "h1x_twfe_ai518210_lag1_ctrl4_w9901_cl-state_coal_share_50s2015_2025"), ("co2_per_mwh_t", "h1x_twfe_ai518210_lag1_ctrl4_w9901_cl-state_co2_per_mwh_t_50s2015_2024"), ("new_renew_mw", "h1x_twfe_ai518210_lag1_ctrl4_w9901_cl-state_new_renew_mw_50s2015_2025"), ("new_renew_mw per 1,000 MW of 2015 capacity", "h1x_rob_twfe_ai518210_lag1_ctrl4_w9901_cl-state_new_renew_per1000mw_50s2015_2025"), ("new_renew_mw per million people", "h1x_rob_twfe_ai518210_lag1_ctrl4_w9901_cl-state_new_renew_per_mpop_50s2015_2025"), ("ln(renewable MWh)", "h1x_twfe_ai518210_lag1_ctrl4_w9901_cl-state_ln_renew_mwh_50s2015_2025"), ("ln(total MWh)", "h1x_twfe_ai518210_lag1_ctrl4_w9901_cl-state_ln_total_mwh_50s2015_2025")]
rows = [dict(Outcome=r.outcome, Group="Core", AI=cl(r.estimate, r.se, r.pval), N=int(r.N)) for r in c.itertuples()]
for nm, t in ex:
    r = x[x.tag == t].iloc[0]; rows.append(dict(Outcome=nm, Group="Extra", AI=cl(r.estimate, r.se, r.pval, 2 if abs(r.estimate) > 5 else 4), N=int(r.N)))
save(pd.DataFrame(rows), "table2_h1", "H1: AI(t-1) with two-way FE, ctrl4, clustered by state. * p<0.1, ** p<0.05, *** p<0.01.")

# ---- Table 3: nonlinearity and heterogeneity ----
n = pd.read_csv(f"{H1}/nonlinearity.csv"); n = n[n.tag.str.contains("ctrl4")]; lm = list(csv.reader(open(f"{H1}/lm_proper.csv"))); lmh = lm[0]; lmd = {r[0]: r[lmh.index("lm_pass") + 1] for r in lm[1:] if r[1] == "ctrl4"}  # The file holds a ctrl5 block, then ctrl4 rows with an extra column
assert len(lmd) == 8 and set(lmd.values()) <= {"TRUE", "FALSE"}, lmd
rows = []
for y in n.outcome.unique():
    a1 = n[(n.outcome == y) & (n.coef == "ai_dc_per1000_lag1")].iloc[0]; a2 = n[(n.outcome == y) & (n.coef == "ai_sq_lag1")].iloc[0]
    rows.append(dict(Outcome=y, AI=cl(a1.estimate, a1.se, a1.pval), AI_squared=cl(a2.estimate, a2.se, a2.pval), Lind_Mehlum_passes=lmd.get(y, "not tested").title(), N=int(a1.N)))
save(pd.DataFrame(rows), "table3a_nonlinearity", "AI squared with ctrl4, clustered. No curve passes the Lind-Mehlum test.")
pd.DataFrame([dict(outcome=k, lm_pass=v) for k, v in lmd.items()]).to_csv(f"{TB}/lind_mehlum_summary.csv", index=False)
h = pd.read_csv(f"{H1}/heterogeneity.csv"); h = h[h.tag.str.contains("ctrl4") & h.coef.str.contains(":")]; hl = pd.read_csv(f"{H1}/het_lincom.csv")
save(pd.DataFrame([dict(Outcome=r.outcome, Interaction=r.coef.replace("ai_lag1_c:", "AI x ").replace("_c", ""), Estimate=cl(r.estimate, r.se, r.pval), N=int(r.N)) for r in h.itertuples()]), "table3b_heterogeneity", "Interactions in one model, ctrl4, clustered. Exploratory. For renew_share, AI x high price: slope -0.0270 in low-price states, 0.0046 in high-price states.")

# ---- Table 4: mediation ----
m = pd.read_csv(f"{H2}/h2_results.csv"); rows = []
for me, lab in (("tech_share_c", "tech_share (H2a main)"), ("hma", "HMA (H2a, memo version)"), ("ln_ea", "ln_ea (H2b)")):
    for y in ("ln_ec", "ln_ee", "renew_share"):
        s = m[(m.mediator == me) & (m.outcome == y)]; a_ = s[s.equation == "eq-a"].iloc[0]; e_ = s[(s.equation == "eq-c") & (s.coef != "ai_dc_per1000_lag1")].iloc[0]; so = s[s.tag.str.endswith("indirect-sobel")].iloc[0]; bo = s[s.tag.str.endswith("indirect-bootstrap")].iloc[0]
        rows.append(dict(Mediator=lab, Outcome=y, AI_to_M=cl(a_.estimate, a_.se, a_.pval, 5), M_to_Y=cl(e_.estimate, e_.se, e_.pval, 3), Indirect=f"{so.estimate:.5f}", Sobel_p=f"{so.pval:.3f}", Bootstrap_95_CI=f"[{bo.ci_lo:.4f}, {bo.ci_hi:.4f}]"))
save(pd.DataFrame(rows), "table4_mediation", "Mediation, ctrl4, clustered. All bootstrap CIs include zero. HMA's first stage is mechanical. Share mediated isn't reported.")
sb = m[m.tag.str.endswith("indirect-sobel")].pval; pd.DataFrame([dict(tag="h2_sobel_summary", n=len(sb), min_p=sb.min(), max_p=sb.max())]).to_csv(f"{TB}/mediation_summary.csv", index=False)

# ---- Table 5: spatial ----
